'use strict';
const groups = [{"id": "lapunta", "number": "01", "title": "La Punta", "timing": "OUR CORNER · ANY FREE AFTERNOON", "color": "pink", "description": "Where we’re staying. Everything here is a short walk from Sicarú, so no taxis needed.", "sections": [["BEACH & SUNSET", [["lapuntabeach", "La Punta beach", "the far end of Zicatela, gentler waves and surfers at the point"], ["puntasunset", "Sunset at the La Punta point", "walk round the rocks at the south end and watch the surfers", "Our Wednesday plan."]]], ["COFFEE AFTER WORK", [["lapuntacoffee", "La Punta Coffee", "small coffee shop just off the main street: açaí bowls, matcha lattes, topped sourdough toast"], ["capsula", "Capsula", "tiny takeaway bar for Mexican specialty coffee: flat whites and iced lattes"], ["sukuun", "Café Suku’un", "espresso bar on the main street: smoothie bowls, juices, iced coffee and pastries"], ["casakooks", "Casa Kooks", "espresso bar from 7:30am, known for espresso tonics and smoothies"], ["blackbaba", "Black Baba", "café for bubble tea, Oaxacan hot chocolate and light food"]]], ["EAT", [["chicama", "Chicama", "Peruvian: ceviche, aguachile and good cocktails; the one everyone recommends, and pricier"], ["alalena", "A La Leña", "wood-fired, thin Italian-style pizza made by the owner"], ["poke", "Poke Surf Club", "build-your-own poke bowls with fresh fish; quick and good value"], ["fishshack", "Fish Shack La Punta", "seafood tacos: grilled garlic prawns, calamari, cauliflower, and coconut dishes"], ["nativo", "Nativo", "simple local seafood: fish fillets, pescadillas and aguas frescas at low prices"], ["pepes", "Pepe’s Fish Tacos", "lively fish and prawn taco place with coconut prawns and a juice of the day"]]], ["DRINKS", [["bikini", "Bikini Bar", "cocktail bar with drinks served in a pineapple, mezcal and chilled music"], ["nodo", "Nodo Brewery", "brewpub with lots of craft beers, bar food, live music and a climbing wall"], ["boneyard", "The Boneyard", "bar beside a skate bowl: pizza, burgers, loaded fries and classic rock"]]], ["IF WE NEED A DESK", [["checowork", "Coworking at Che hostel", "coworking space in the Che hostel, with a pool and rooftop; ask about a day pass"], ["coworkpuerto", "Cowork Puerto", "coworking in town with reliable internet for calls"], ["malagua", "Malagua Café", "the big breakfast place: eggs Benedict, omelettes, good coffee; busy, so service can be slow"]]]], "note": "Cafés, food and coworking don’t count towards progress: tick them if you like."}, {"id": "carrizalillo", "number": "02", "title": "Carrizalillo, Rinconada & the turtles", "timing": "ONE AFTERNOON · FRIDAY SUITS IT", "color": "blue", "description": "A swim, a late lunch, then baby turtles and sunset on Bacocho. All close together on the north side of town.", "sections": [["SWIM", [["carrizalillobeach", "Playa Carrizalillo", "small sheltered cove, about 160 steps down", "Calm enough to swim. Save energy for the steps back up."]]], ["LATE LUNCH IN RINCONADA", [["tentate", "Tentate 777", "small brunch café-bar: big breakfasts, yoghurt bowls, brownies"]]], ["TURTLES & SUNSET", [["turtles", "Baby turtle release at Vive Mar", "on Playa Bacocho, about 150 pesos, cash", "No booking. Be there by 4:45pm; the release is around 6. It depends on what hatched that morning, so ask locally first.", [["About Vive Mar", "https://www.mexicodesconocido.com.mx/liberacion-de-tortugas-recien-nacidas-en-puerto-escondido-una-experiencia-que-jamas-olvidaras.html"]]], ["bacocho", "Sunset on Playa Bacocho", "long beach for walking, not swimming: the currents are strong"]]]], "note": "Finish work by about 1pm for a proper swim. Short on time? Cut the beach, not the turtles. Ask the camp or a hotel nearby to call a taxi home after dark."}, {"id": "lagoon", "number": "★", "title": "Laguna Manialtepec by night", "timing": "SUNDAY EVENING", "color": "blue", "description": "A boat across the dark lagoon, where every trail of the paddle and every hand in the water glows blue. About 30 minutes west of town, back late.", "sections": [["THE GLOWING LAGOON", [["manialtepec", "Bioluminescence boat trip", "about 2.5–3.5 hours with pickup", "All three include pickup; the Viator boat ride is the best-reviewed, about £38 each.", [["Bioluminescent Lagoon Boat Ride and Swim", "https://www.viator.com/tours/Puerto-Escondido/Bioluminescent-Lagoon-Boat-Ride-and-Swim-from-Puerto-Escondido/d23875-31331P3"], ["Roberts Ecotours night tour", "https://www.travelocity.com/things-to-do/bioluminescent-night-tour.a1007908.activity-details"], ["Lalo Ecotours", "https://yumping.com/en/water-sports/lalo-eco-tours--e19664927"]]]]]], "note": "The glow is brightest on dark nights. Mid-November has a young moon that sets late evening, so ask for the latest departure. The glow varies and is never guaranteed."}, {"id": "angelito", "number": "03", "title": "Puerto Angelito & Manzanillo", "timing": "OUR LAST AFTERNOON · THURSDAY", "color": "green", "description": "Two calm little bays side by side, good for swimming and snorkelling.", "sections": [["TWO COVES", [["angelitobeach", "Playa Puerto Angelito", "calm water, boats and beach restaurants"], ["manzanillo", "Playa Manzanillo", "next door, a few steps along the rocks"]]]], "note": "Fewer steps than Carrizalillo, and an easy last swim before packing. Back before dark is easiest."}, {"id": "town", "number": "04", "title": "Into town", "timing": "WHENEVER WE FANCY A CHANGE", "color": "pink", "description": "The real town, ten minutes up the coast road.", "sections": [["A SHORT WANDER", [["mercado", "Mercado Benito Juárez", "the town market: fruit, juices and cheap lunches"], ["adoquin", "El Adoquín", "the pedestrian strip by the main bay, with the tourist booth"], ["binisa", "Café Binisa", "local café for iced coffee, pour-overs and cappuccinos; no wifi"]]]], "note": "Colectivos run along the coast road for about 8–12 pesos."}, {"id": "mazunte", "number": "SAT", "title": "Mazunte & Punta Cometa", "timing": "OUR BIG DAY OUT · A FULL SATURDAY", "color": "pink", "weekend": true, "description": "A village beach, the turtle centre, a look at San Agustinillo and Zipolite, then sunset from the headland. About an hour down the coast.", "table": {"caption": "How to get to Mazunte", "map": "Map", "days": [["Tours · hotel pickup and drop-off", [["10am–7pm", "★ Experiencias Nativas · my pick", "Mazunte, Zipolite and the Punta Cometa sunset, with the ride home sorted. About €60 each.", "Pickup in Puerto Escondido", "Mazunte Oaxaca", "https://www.ebookers.ie/things-to-do/mazunte-ventanilla-and-zipolite-ecotour.a52131871.activity-details"], ["9am–8:30pm", "Ocean Travel · Estacahuite to Punta Cometa", "Snorkelling at Estacahuite first, then Mazunte and sunset. From 1,369 pesos each.", "Pickup in Puerto Escondido", "Playa Estacahuite Oaxaca", "https://oceantravel.nodo5.com/en/en-que-plan-viajas/detalles/desde-puerto-escondido-estacahuite-a-punta-cometa-un-dia-de-aventura-costera"], ["About 10 hours", "GetYourGuide · Mazunte and Zipolite day tour", "Turtle centre, Zipolite and the Punta Cometa sunset. Food and Punta Cometa entry are extra.", "Pickup in Puerto Escondido", "Centro Mexicano de la Tortuga Mazunte", "https://www.clicatour.com/en/excursion/mexico/oaxaca/puerto-escondido-dagtour-mazunte-en-zipolite-1742676412"]]], ["Taxi · our own pace", [["All day", "Taxi or driver for the day", "No group. 1,300–1,600 pesos return for both of us with waiting, or 800–1,100 one way. Fix the return time first.", "About 1 hour each way", "Mazunte Oaxaca"]]], ["Scooter · daylight only", [["Back by dark", "Rent a scooter", "About 500 pesos a day; both of us on one, helmets on. Ride back before dark, so no Punta Cometa sunset. Check the travel insurance covers it.", "67 km each way on Highway 200", "Mazunte Oaxaca"]]], ["Bus · cheapest", [["2–3 hours", "Bus, then colectivo from Pochutla", "About 210 pesos each per way. Easy going there; awkward coming back after sunset.", "Change at Pochutla", "Pochutla Oaxaca"]]]]}, "sections": [["IN MAZUNTE", [["mazuntebeach", "Mazunte village & beach", "lunch, a swim and a wander"], ["tortuga", "Centro Mexicano de la Tortuga", "the national turtle centre on the hill"]]], ["ALONG THE COAST", [["sanagustinillo", "San Agustinillo", "small village bay between Mazunte and Zipolite, good for a swim"], ["zipolite", "Zipolite", "long, wild beach just past it"]]], ["SUNSET", [["puntacometa", "Punta Cometa", "short walk up the headland; go 45 minutes before sunset"]]]], "note": "Whichever way we go, sort the ride home before we leave: there’s no Uber, and taxis are scarce in Mazunte after dark."}];
const optional = [["dolphins", "Dolphin and turtle boat trip", "an early morning, about 3 hours", "Roberts Ecotours: 3.5 hours from 6:30am, snorkel gear and pickup included. Whales are unlikely in mid-November.", [["Roberts Ecotours", "https://www.robertsecotours.com/"], ["Eco Adventures", "https://wildlifenomads.com/find-a-wildlife-guide-tour/eco-adventures-puerto-escondido"]]], ["horseride", "Horse ride to the Atotonilco hot springs", "an early morning, about 4–5 hours", "Eco Adventures (take the 6am slot), Experiencias Nativas or Lalo Ecotours. Mornings only: the rivers rise later.", [["Experiencias Nativas", "https://www.viator.com/en-GB/tours/Puerto-Escondido/Horses-in-Manialtepec/d23875-116123P1"], ["Eco Adventures", "https://wildlifenomads.com/find-a-wildlife-guide-tour/eco-adventures-puerto-escondido"], ["Lalo Ecotours", "https://yumping.com/en/water-sports/lalo-eco-tours--e19664927"]]], ["surf", "A beginner surf lesson", "late afternoon in La Punta, about 600–1,000 pesos", "", [["Beginner surf lessons", "https://www.clicatour.com/en/excursion/mexico/oaxaca/surflessen-in-puerto-escondido"]]]];
const KEY='frolicking-nicky-puerto-escondido-v1';
let checked={}; let storageOK=true;
try { const saved=JSON.parse(localStorage.getItem(KEY)||'{}'); if(saved && typeof saved==='object' && !Array.isArray(saved)) checked=saved; } catch {storageOK=false;}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const OPTIONAL_IDS=new Set(["lapuntacoffee", "capsula", "sukuun", "malagua", "casakooks", "blackbaba", "chicama", "alalena", "poke", "fishshack", "nativo", "boneyard", "bikini", "nodo", "checowork", "coworkpuerto", "binisa", "pepes", "tentate"]);
const countedIds=()=>groups.filter(()=>true).flatMap(g=>g.sections.flatMap(s=>s[1].map(r=>r[0]))).filter(id=>!OPTIONAL_IDS.has(id));
function item(row,extra=false) {const [id,title,desc,note,links]=row;return `<label class="task${checked[id]===true?' completed':''}"><input type="checkbox" id="${esc(id)}" data-extra="${extra}" ${checked[id]===true?'checked':''}><span class="checkmark" aria-hidden="true"></span><span class="task-copy"><span class="task-title">${esc(title)}</span> <span class="specialty">(${esc(desc)})</span>${note?`<span class="task-note">${esc(note)}</span>`:''}${links&&links.length?`<span class="fn-task-links">${links.map(([l,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(l)} ↗︎</a>`).join('')}</span>`:''}</span></label>`;}
const PHOTOS={"lapunta": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Surf_at_Sunset_-_Zicatela_Beach_-_Puerto_Escondido_-_Oaxaca_-_Mexico_%286533419239%29.jpg/1280px-Surf_at_Sunset_-_Zicatela_Beach_-_Puerto_Escondido_-_Oaxaca_-_Mexico_%286533419239%29.jpg", "Surfers on a golden evening wave at Zicatela", 1280, 960, "Adam Jones", "CC BY-SA 2.0", "https://commons.wikimedia.org/wiki/File:Surf_at_Sunset_-_Zicatela_Beach_-_Puerto_Escondido_-_Oaxaca_-_Mexico_(6533419239).jpg"]]], "carrizalillo": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Playa_Carrizalillo_Puerto_Escondido.jpg/1280px-Playa_Carrizalillo_Puerto_Escondido.jpg", "The small sheltered cove of Playa Carrizalillo between green cliffs", 1280, 851, "elfidomx", "CC BY 2.0", "https://commons.wikimedia.org/wiki/File:Playa_Carrizalillo_Puerto_Escondido.jpg"]], [], [["https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/Olive_ridley_hatchling_in_Mexico_%288218893828%29.jpg/1280px-Olive_ridley_hatchling_in_Mexico_%288218893828%29.jpg", "A baby olive ridley turtle on wet sand", 1280, 1073, "Steve Jurvetson", "CC BY 2.0", "https://commons.wikimedia.org/wiki/File:Olive_ridley_hatchling_in_Mexico_(8218893828).jpg"]]], "lagoon": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Laguna_de_Manialtepec_Oaxaca.jpg/1280px-Laguna_de_Manialtepec_Oaxaca.jpg", "Mangroves along the still water of Laguna Manialtepec", 1280, 960, "Lunita28mx", "CC BY 4.0", "https://commons.wikimedia.org/wiki/File:Laguna_de_Manialtepec_Oaxaca.jpg"], ["https://upload.wikimedia.org/wikipedia/commons/thumb/5/5a/Pelicanos_en_la_laguna_Manialtepec.JPG/1280px-Pelicanos_en_la_laguna_Manialtepec.JPG", "Pelicans resting on branches over Laguna Manialtepec", 1280, 852, "Jaumahell", "CC BY-SA 3.0", "https://commons.wikimedia.org/wiki/File:Pelicanos_en_la_laguna_Manialtepec.JPG"]]], "angelito": [[["https://upload.wikimedia.org/wikipedia/commons/4/41/Puerto_Angelito%2C_Oaxaca._-_panoramio.jpg", "Boats and swimmers in the calm bay of Puerto Angelito", 1000, 654, "holachetumal", "CC BY 3.0", "https://commons.wikimedia.org/wiki/File:Puerto_Angelito,_Oaxaca._-_panoramio.jpg"]]], "town": [], "mazunte": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/f/fb/Mazunte_beach_from_the_Turtle_Center.jpg/1280px-Mazunte_beach_from_the_Turtle_Center.jpg", "Mazunte beach seen from the turtle centre on the hill", 1280, 960, "Tvdp77", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Mazunte_beach_from_the_Turtle_Center.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/5/5d/ZipoliteFromAmor.JPG/1280px-ZipoliteFromAmor.JPG", "The long curve of Zipolite beach seen from the hill", 1280, 857, "AlejandroLinaresGarcia", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:ZipoliteFromAmor.JPG"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/Punta_Cometa%2C_Mazunte%2C_Oaxaca.jpg/1280px-Punta_Cometa%2C_Mazunte%2C_Oaxaca.jpg", "The grassy headland of Punta Cometa above the Pacific", 1280, 853, "Anna Bertho", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Punta_Cometa,_Mazunte,_Oaxaca.jpg"]]]};
const fig=([src,alt,w,h,by,lic,url])=>`<figure class="fn-v-photo"><a href="${src}" target="_blank" rel="noopener"><img src="${src}" alt="${esc(alt)}" width="${w}" height="${h}" loading="lazy"></a>${by?`<figcaption>Photo: ${by} · <a href="${url}" target="_blank" rel="noopener noreferrer">${lic}</a></figcaption>`:''}</figure>`;
const muertosTable=t=>{const pick=(()=>{const d=new Date();const k=(d.getMonth()+1)*100+d.getDate();return {1031:1,1101:2,1102:3}[k]??0;})();return `<div class="fn-plan-tabs" role="tablist" aria-label="${esc(t.caption)}">${t.days.map(([day],i)=>`<button type="button" role="tab" id="fn-plan-tab-${i}" aria-controls="fn-plan-day-${i}" aria-selected="${i===pick}" tabindex="${i===pick?0:-1}">${esc(day.split(' · ')[0])}</button>`).join('')}</div>${t.days.map(([day,rows],i)=>`<div class="fn-plan-panel" role="tabpanel" id="fn-plan-day-${i}" aria-labelledby="fn-plan-tab-${i}"${i===pick?'':' hidden'}>${day.includes(' · ')?`<p class="fn-plan-sub">${esc(day.split(' · ').slice(1).join(' · '))}</p>`:''}<ol class="fn-plan-stops">${rows.map(([when,plan,what,where,q,url])=>`<li${/★/.test(plan)?' class="fn-plan-star"':''}><span class="fn-plan-when">${esc(when)}</span><div><p class="fn-plan-name">${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(plan)} ↗︎</a>`:esc(plan)}</p><p class="fn-plan-what">${esc(what)}</p><p class="fn-plan-where">${esc(where)} <a class="fn-plan-map" href="https://www.google.com/maps/search/?api=1&amp;query=${encodeURIComponent(q)}" target="_blank" rel="noopener noreferrer">${esc(t.map)}</a></p></div></li>`).join('')}</ol></div>`).join('')}`;};
let rowN=0;
document.querySelector('#itinerary').innerHTML=groups.map(g=>`<section id="${g.id}" class="outing fn-split ${g.color} ${g.weekend?'weekend':''}" aria-labelledby="title-${g.id}"><div class="outing-heading"><span class="number" aria-hidden="true">${g.number}</span><div><p class="eyebrow">${g.timing}</p><h2 id="title-${g.id}">${g.title}</h2><p class="section-desc">${g.description}</p></div><span class="group-count" id="count-${g.id}" aria-label="Section completion"></span></div>${g.table?`<div class="fn-plan-wrap">${muertosTable(g.table)}</div>`:''}<div class="outing-body fn-split-body"${g.sections.length?'':' hidden'}>${g.sections.map(([title,rows],si)=>{const ps=(PHOTOS[g.id]||[])[si]||[];const card=`<div class="task-group"><h3>${title}</h3>${rows.map(r=>item(r,OPTIONAL_IDS.has(r[0]))).join('')}</div>`;return ps.length?`<div class="fn-v-row${rowN++%2?' fn-v-rev':''}"><div class="fn-v-side">${ps.map(fig).join('')}</div>${card}</div>`:card;}).join('')}</div><div class="outing-note"><p>${g.note}</p>${g.link?`<a href="${g.link[1]}" target="_blank" rel="noopener noreferrer">${g.link[0]} ↗︎</a>`:''}</div></section>`).join('');
document.querySelectorAll('.fn-plan-tabs').forEach(list=>{const tabs=[...list.querySelectorAll('[role=tab]')];const show=(tab,focus)=>{tabs.forEach(b=>{const on=b===tab;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;document.getElementById(b.getAttribute('aria-controls')).hidden=!on;});if(focus)tab.focus();};tabs.forEach((b,i)=>{b.addEventListener('click',()=>show(b));b.addEventListener('keydown',e=>{const n={ArrowRight:i+1,ArrowLeft:i-1,Home:0,End:tabs.length-1}[e.key];if(n===undefined)return;e.preventDefault();show(tabs[(n+tabs.length)%tabs.length],true);});});});
document.querySelector('#optional-list').innerHTML=optional.map(r=>item(r,true)).join('');
function update(announce=false){const mainIds=countedIds();const done=mainIds.filter(id=>checked[id]===true).length;const percent=Math.round(done/mainIds.length*100);document.querySelector('#progress-count').textContent=done;document.querySelector('#progress-total').textContent=`of ${mainIds.length} places & moments`;document.querySelector('#percent').textContent=percent+'%';document.querySelector('#progress').value=percent;document.querySelector('#progress').textContent=percent+'%';groups.forEach(g=>{const inactive=false;const ids=g.sections.flatMap(s=>s[1].map(r=>r[0])).filter(id=>!OPTIONAL_IDS.has(id));document.querySelector('#count-'+g.id).hidden=!ids.length;document.querySelector('#count-'+g.id).textContent=inactive?"Alternative: excluded from checklist":`${ids.filter(id=>checked[id]===true).length} / ${ids.length}`;});const extra=[...optional.map(r=>r[0]),...OPTIONAL_IDS].filter(id=>checked[id]===true).length;document.querySelector('#extra-count').textContent=`${extra} optional ${extra===1?'stop':'stops'} done`;document.querySelector('#save-note').textContent=storageOK?'Progress saved on this device.':'Progress works here, but saving is unavailable in this browser.';if(announce)document.querySelector('#announcement').textContent=`${done} of ${mainIds.length} main items complete. ${extra} optional stops done.`;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(checked));storageOK=true;}catch{storageOK=false;}}
document.addEventListener('change',e=>{if(!e.target.matches('.task input'))return;checked[e.target.id]=e.target.checked;e.target.closest('.task').classList.toggle('completed',e.target.checked);persist();update(true);});
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{const next=JSON.parse(e.newValue||'{}');checked=next&&typeof next==='object'&&!Array.isArray(next)?next:{};}catch{checked={};}document.querySelectorAll('.task input').forEach(el=>{el.checked=checked[el.id]===true;el.closest('.task').classList.toggle('completed',el.checked);});update();});
const dialog=document.querySelector('#reset-dialog');document.querySelector('#reset').addEventListener('click',()=>dialog.showModal());document.querySelector('#cancel-reset').addEventListener('click',()=>dialog.close());document.querySelector('#confirm-reset').addEventListener('click',()=>{checked={};persist();document.querySelectorAll('.task input').forEach(el=>{el.checked=false;el.closest('.task').classList.remove('completed');});update(true);dialog.close();});
update();
